"""Video mapping model for old YouTube video to new local content."""

from pathlib import Path

from pydantic import BaseModel, Field


class VideoMapping(BaseModel):
    """Maps existing YouTube video to new local video content.

    Attributes:
        youtube_video_id: Existing YouTube video ID to update
        new_video_path: Path to new synchronized video file
        alya_id: Foreign key to alyot table (replaces parasha_name/aliyah_name)
        preserve_thumbnail: Whether to preserve existing thumbnail
        preserve_metadata: Whether to preserve existing metadata
    """

    youtube_video_id: str = Field(..., description="YouTube video ID to update")
    new_video_path: Path = Field(..., description="New video file path")
    alya_id: int = Field(..., description="FK to alyot.id")
    preserve_thumbnail: bool = Field(True, description="Preserve thumbnail")
    preserve_metadata: bool = Field(
        False, description="Preserve existing metadata (or update with CIFRIA)"
    )

    def validate_new_video_exists(self) -> bool:
        """Validate new video file exists.

        Returns:
            True if file exists, False otherwise
        """
        return self.new_video_path.exists()
